<?php
require 'config/database.php';$id=(int)($_GET['id']??0);$stmt=$conn->prepare("SELECT a.application_id,a.application_date,j.company_name,j.title,j.location,j.salary,u.name,u.email,s.phone FROM applications a JOIN jobs j ON j.job_id=a.job_id JOIN users u ON u.user_id=a.seeker_id JOIN job_seekers s ON s.seeker_id=a.seeker_id WHERE a.application_id=? AND a.status='Accepted' AND a.candidate_response='Accepted'");$stmt->bind_param('i',$id);$stmt->execute();$row=$stmt->get_result()->fetch_assoc();
if(!$row){http_response_code(403);die('<h2 style="font-family:Arial">Accept the selected job offer before downloading the Appointment Letter.</h2>');}
$issueDate=date('F d, Y');$joinDate=date('F d, Y',strtotime('+14 days'));
?>
